INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 7001, -363.0, 1, 0.0, 1, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 7, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 7002, -363.0, 1, 0.0, 1, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 7, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 7003, -363.0, 1, 0.0, 1, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 7, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 10001, -363.0, 1, 0.0, 1, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 10, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 10002, -363.0, 1, 0.0, 1, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 10, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 10003, -363.0, 1, 0.0, 1, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 10, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 10004, -363.0, 1, 0.0, 2, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 10, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 12001, -416.5, 1, 0.0, 1, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 12, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 13001, -363.0, 1, 0.0, 1, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 13, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 13002, -363.0, 1, 0.0, 1, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 13, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 13003, -363.0, 1, 0.0, 2, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 13, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 13004, -363.0, 1, 0.0, 1, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 13, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 14001, -363.0, 1, 0.0, 1, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 14, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 14002, -363.0, 1, 0.0, 2, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 14, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 14003, -363.0, 1, 0.0, 1, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 14, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 14004, -363.0, 1, 0.0, 1, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 14, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 15001, -470.0, 1, 0.0, 1, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 15, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 16001, -363.0, 1, 0.0, 2, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 16, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 16002, -363.0, 1, 0.0, 1, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 16, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 16003, -363.0, 1, 0.0, 1, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 16, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 16004, -363.0, 1, 0.0, 1, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 16, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 17002, -363.0, 1, 0.0, 1, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 17, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 17004, -363.0, 1, 0.0, 1, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 25, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 17005, -363.0, 1, 0.0, 1, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 25, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 17006, -363.0, 1, 0.0, 2, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 25, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 17007, -363.0, 1, 0.0, 1, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 25, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 18001, -363.0, 1, 0.0, 1, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 18, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 18002, -363.0, 2, 0.0, 1, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 18, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 19001, -470.0, 3, 0.0, 1, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 19, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 19002, -470.0, 4, 0.0, 1, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 19, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 20001, -470.0, 5, 0.0, 1, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 20, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 20002, -470.0, 6, 0.0, 1, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 20, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 21001, -363.0, 1, 0.0, 1, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 21, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 21002, -363.0, 1, 0.0, 1, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 21, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 21003, -363.0, 1, 0.0, 2, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 21, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 21004, -363.0, 1, 0.0, 1, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 21, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 22001, -430.0, 1, 0.0, 1, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 22, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 22002, -430.0, 2, 0.0, 1, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 22, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 23001, -430.0, 3, 0.0, 1, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 23, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 23002, -430.0, 4, 0.0, 1, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 23, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24001, -385.0, 1, 4.08, 1, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 24, 10011, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24002, -385.0, 2, 5.0, 1, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 24, 10011, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24003, -385.0, 3, 10.11, 1, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 24, 10011, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24004, -385.0, 4, 4.0, 1, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 24, 10011, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24005, -385.0, 5, 6.0, 1, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 24, 10011, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24006, 0.0, 6, 0.0, 1, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 24, 10011, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24007, 0.0, 7, 0.0, 1, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 24, 10011, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24008, 0.0, 8, 0.0, 1, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 24, 10011, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24009, 0.0, 9, 0.0, 1, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 24, 10011, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "エリコ（バレンタイン）", 0, "2019/01/31 12:00:00", 24010, 0.0, 10, 0.0, 1, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 24, 10011, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24011, -385.0, 1, 2.12, 1, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 24, 10011, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24012, -385.0, 2, 4.19, 5, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 24, 10011, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (4, 8.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24013, -385.0, 3, 2.3, 2, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 24, 10011, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24014, 0.0, 4, 0.0, 1, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 24, 10011, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24015, -385.0, 5, 5.23, 5, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 24, 10011, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24016, 0.0, 6, 0.0, 1, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 24, 10011, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 8.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24017, -385.0, 7, 5.01, 1, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 24, 10011, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24018, 0.0, 8, 0.0, 1, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 24, 10011, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24019, 0.0, 9, 0.0, 1, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 24, 10011, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シズル（バレンタイン）", 0, "2019/01/31 12:00:00", 24020, 0.0, 10, 0.0, 1, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 24, 10011, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 26001, -363.0, 1, 0.0, 2, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 26, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 26002, -363.0, 1, 0.0, 1, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 26, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 26003, -363.0, 1, 0.0, 1, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 26, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 26004, -363.0, 1, 0.0, 1, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 26, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 27001, -363.0, 1, 0.0, 2, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 27, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 27002, -363.0, 1, 0.0, 1, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 27, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 27003, -363.0, 1, 0.0, 1, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 27, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 27004, -363.0, 1, 0.0, 1, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 27, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/09/24 15:00:00", 28001, -363.0, 1, 0.0, 1, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 28, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/09/24 15:00:00", 28002, -363.0, 2, 0.0, 1, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 28, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/09/24 15:00:00", 29001, -409.0, 3, 0.0, 1, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 29, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/09/24 15:00:00", 29002, -409.0, 4, 0.0, 1, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 29, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/09/24 15:00:00", 30001, -409.0, 5, 0.0, 1, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 30, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/09/24 15:00:00", 30002, -409.0, 6, 0.0, 1, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 30, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/10/31 12:00:00", 31001, -409.0, 7, 0.0, 1, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 31, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2019/10/31 12:00:00", 31002, -409.0, 8, 0.0, 1, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 31, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2020/01/04 4:59:59", "カリン", 0, "2019/12/20 5:00:00", 32001, -409.0, 1, 0.0, 1, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 32, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2020/01/04 4:59:59", "カリン", 0, "2019/12/20 5:00:00", 32002, -409.0, 2, 0.0, 1, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 32, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2020/01/04 4:59:59", "カリン", 0, "2019/12/20 5:00:00", 33001, -409.0, 3, 0.0, 1, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 33, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2020/01/04 4:59:59", "カリン", 0, "2019/12/20 5:00:00", 33002, -409.0, 4, 0.0, 1, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 33, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2020/01/10 11:59:59", "カリン", 0, "2020/01/04 5:00:00", 34001, -409.0, 5, 0.0, 1, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 34, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2020/01/10 11:59:59", "カリン", 0, "2020/01/04 5:00:00", 34002, -409.0, 6, 0.0, 1, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 34, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 38001, -458.0, 1, 5.3, 1, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 38, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 38002, -458.0, 2, 6.5, 1, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 38, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (3, 9999.0, "2020/04/08 23:59:59", "ペコリーヌ", 0, "2020/04/01", 39005, 9999.0, 0, 0.0, 3, "", 39, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "カリン", 0, "2015/12/17 15:00:00", 40001, -430.0, 2, 0.0, 1, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 40, 0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 41001, -363.0, 1, 0.0, 1, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 41, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 41002, -363.0, 1, 0.0, 1, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 41, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 41003, -363.0, 1, 0.0, 1, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 41, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 41004, -363.0, 1, 0.0, 1, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 41, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 42001, -416.5, 1, 0.0, 1, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 42, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "シェフィ", 2104010, "2015/12/17 15:00:00", 42002, -416.5, 1, 0.0, 1, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 42, 0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 42003, -416.5, 1, 0.0, 1, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 42, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 42004, -416.5, 1, 0.0, 1, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 42, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "ペコリーヌ", 0, "2015/12/17 15:00:00", 43001, -363.0, 1, 0.0, 1, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 43, 0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "コッコロ", 0, "2015/12/17 15:00:00", 43002, -363.0, 1, 0.0, 1, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 43, 0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "キャル", 0, "2015/12/17 15:00:00", 43003, -363.0, 1, 0.0, 1, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 43, 0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "アメス", 0, "2015/12/17 15:00:00", 43004, -416.5, 1, 0.0, 1, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 44, 0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "アメス", 0, "2015/12/17 15:00:00", 43005, -416.5, 2, 0.0, 1, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 44, 0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, "2030/12/17 14:59:59", "アメス", 0, "2015/12/17 15:00:00", 43006, -416.5, 3, 5.79, 1, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 45, 0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (1, 0.0, "2030/12/17 14:59:59", "アメス", 0, "2015/12/17 15:00:00", 46001, -371.5, 1, 0.0, 1, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 46, 0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, "2030/12/17 14:59:59", "シズル", 0, "2015/12/17 15:00:00", 47001, -416.5, 1, 0.0, 2, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 47, 0, 104901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2, 0.0, "2030/12/17 14:59:59", "リノ", 0, "2015/12/17 15:00:00", 47002, -416.5, 1, 9.32, 1, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 47, 0, 101101);
